      out.write("                });\r\n");
      out.write("\r\n");
      out.write("                // 3. Gráfica de Pastel (Categorías)\r\n");
      out.write("                new Chart(document.getElementById('chartCategories'), {\r\n");
      out.write("                    type: 'doughnut',\r\n");
      out.write("                    data: {\r\n");
      out.write("                        labels: catDataLabels,\r\n");
      out.write("                        datasets: [{ \r\n");
      out.write("                            data: catDataValues, \r\n");
      out.write("                            backgroundColor: ['#00d4ff', '#ffc107', '#ff4444', '#00ff88', '#9d00ff', '#f39c12', '#e74c3c'],\r\n");
      out.write("                            borderWidth: 0\r\n");
      out.write("                        }]\r\n");
      out.write("                    },\r\n");
      out.write("                    options: { \r\n");
      out.write("                        responsive: true, \r\n");
      out.write("                        plugins: { legend: { position: 'bottom', labels: { color: '#fff', padding: 20 } } },\r\n");
      out.write("                        onClick: (evt, item) => {\r\n");
      out.write("                            if (item.length > 0) {\r\n");
      out.write("                                const index = item[0].index;\r\n");
      out.write("                                const catName = catDataLabels[index];\r\n");
      out.write("                                mostrarDetalle(catName);\r\n");
      out.write("                            }\r\n");
      out.write("                        }\r\n");
      out.write("                    }\r\n");
      out.write("                });\r\n");
      out.write("\r\n");
      out.write("                function mostrarDetalle(categoria) {\r\n");
      out.write("                    const filtered = masterProducts.filter(p => p.categoria === categoria);\r\n");
      out.write("                    document.getElementById('modalTitle').innerText = \"Productos en: \" + categoria;\r\n");
      out.write("                    const tbody = document.getElementById('tableBodyDetalle');\r\n");
      out.write("                    tbody.innerHTML = filtered.map(function(p) {\r\n");
      out.write("                        return '<tr>' +\r\n");
      out.write("                            '<td>' + p.nombre + '</td>' +\r\n");
      out.write("                            '<td class=\"text-info\">$' + p.precio + '</td>' +\r\n");
      out.write("                            '<td class=\"text-center fw-bold ' + (p.stock < 5 ? 'text-danger' : 'text-success') + '\">' + p.stock + '</td>' +\r\n");
      out.write("                            '</tr>';\r\n");
      out.write("                    }).join('');\r\n");
      out.write("                    \r\n");
      out.write("                    const myModal = new bootstrap.Modal(document.getElementById('modalDetalleCat'));\r\n");
      out.write("                    myModal.show();\r\n");
      out.write("                }\r\n");
      out.write("            } catch (err) {\r\n");
      out.write("                console.error(\"Error inicializando el Intelligence Center:\", err);\r\n");
      out.write("            }\r\n");
      out.write("        });\r\n");
